from collections import deque
def comps(g,c):
    R,C=len(g),len(g[0]); seen=set(); res=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==c and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<R and 0<=b<C and g[a][b]==c and (a,b) not in seen:
                                seen.add((a,b)); q.append((a,b))
                res.append(cells)
    return res
for name,g in (('demo',inp),):
    for c in sorted({v for row in g for v in row}):
        cs=comps(g,c)
        if c in (6,): continue
        print(name,'color',c,'ncomps',len(cs))
        for cells in cs:
            ys=[a for a,b in cells]; xs=[b for a,b in cells]
            h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
            print('   size',len(cells),'bbox',h,'x',w,'at',(min(ys),min(xs)))

