def allcomps(g):
    R,C=len(g),len(g[0]); seen=set(); res=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]!=0 and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        a,b=y+dy,x+dx
                        if 0<=a<R and 0<=b<C and g[a][b]==c and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                res.append((c,cells))
    return res
def shape(cells):
    ys=[a for a,b in cells]; xs=[b for a,b in cells]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
